WITH fixes(slug,pos,why) AS (VALUES ('legislacao-icn-revisao',1,'Correto. A Lei 13.444/2017 atribui ao Tribunal Superior Eleitoral a gestão e o armazenamento da base da Identificação Civil Nacional. Atenção: integrar dados de outras fontes não transfere automaticamente a gestão da base.'),
('legislacao-icn-revisao',3,'Correto. A redação atual da Lei 13.444/2017, alterada pela Lei 14.534/2023, estabelece o CPF como número único nos novos Documentos Nacionais de Identidade. Não confunda DNI, ICN e CIN.'),
('legislacao-sic-revisao',1,'Correto. O Decreto 11.797/2023 exige que a disponibilização de informações no Serviço de Identificação do Cidadão respeite o sigilo legal e as normas de proteção de dados pessoais. Integração não significa acesso irrestrito.'),
('legislacao-sic-revisao',3,'Correto. No Serviço de Identificação do Cidadão, o CPF funciona como chave de vinculação dos dados da pessoa natural. É um identificador de registros, não uma senha de autenticação.'),
('legislacao-sic-revisao',5,'Correto. O Decreto 11.797/2023 disciplina procedimentos de identificação e dados cadastrais no Serviço de Identificação do Cidadão. O serviço não se confunde com o documento físico de identidade.'),
('legislacao-sic-revisao',7,'Correto. O Decreto 11.797/2023 prevê hipóteses de utilização facultativa do SIC, inclusive para identificação criminal. A regra geral de integração não pode ser aplicada sem observar essas exceções.'),
('legislacao-uso-forca-revisao',3,'Correto. O art. 4º do Decreto 12.341/2024 estabelece capacitação anual sobre uso da força, em horário de serviço. Não confunda essa periodicidade com o prazo de renovação de habilitação para arma previsto em regulamentação própria.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;